#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> board(8);
    for (auto& row : board) cin >> row;

    int white = 8, black = 8;

    for (int r = 0; r < 8; ++r) {
        for (int c = 0; c < 8; ++c) {
            if (board[r][c] == 'W') {
                bool clear = true;
                for (int i = 0; i < r; ++i) {
                    if (board[i][c] != '.') {
                        clear = false;
                        break;
                    }
                }
                if (clear) white = min(white, r);
            } else if (board[r][c] == 'B') {
                bool clear = true;
                for (int i = r + 1; i < 8; ++i) {
                    if (board[i][c] != '.') {
                        clear = false;
                        break;
                    }
                }
                if (clear) black = min(black, 7 - r);
            }
        }
    }

    cout << (white <= black ? 'A' : 'B') << '\n';
    return 0;
}

